/** Desk's start state in a new session. */
export function desk(session: string, transport: Transport, log?: Log, newId?: () => string): DeskS1 {
  return new DeskS1(new Endpoint("Desk", session, transport, log, newId));
}

/** Librarian at S1: receive(msg): Hold from Desk; skip -> End (the branch taken did not involve this role). */
export class LibrarianS1 extends State {
  readonly state = "LibrarianS1" as const;

  receive(msg: Message): { label: "Hold"; msg: Message; next: LibrarianS2 } {
    const ep = this.ep;
    if (ep.accepts(msg, "Desk", "Hold")) {
      this.take();
      ep.received(msg, "h");
      return { label: "Hold", msg, next: new LibrarianS2(ep) };
    }
    return ep.refuse("LibrarianS1", msg, "Hold from Desk");
  }

  skip(): End { return new End(this.take()); }
}

/** Librarian at S2: sendApproved -> End; sendDenied -> End. */
export class LibrarianS2 extends State {
  readonly state = "LibrarianS2" as const;

  sendApproved(body?: Approved): End {
    const ep = this.take();
    ep.send("Desk", "Approved", null, "h", body);
    return new End(ep);
  }

  sendDenied(body?: Denied): End {
    const ep = this.take();
    ep.send("Desk", "Denied", null, "h", body);
    return new End(ep);
  }
}

/** Librarian's start state in a new session. */
export function librarian(session: string, transport: Transport, log?: Log, newId?: () => string): LibrarianS1 {
  return new LibrarianS1(new Endpoint("Librarian", session, transport, log, newId));
}
